// src/builder/heading.ts
var HEADING_SIGN = "#";
function heading(type, value) {
  return {
    toString() {
      const headingSignCount = Number(type.slice(1));
      const headingSign = HEADING_SIGN.repeat(headingSignCount);
      return `${headingSign} ${value.toString()}`;
    }
  };
}
export {
  heading
};
